<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{ReceiptImporter,OperatorReadModel,OperatorPanel,VersionedMutationHost,MutationFence,ProviderReceipt};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionOperationsTest extends TestCase {
 private function setupCore():array {require_once __DIR__.'/../fixtures/printify-connector/batch3/SyntheticInspectionCore.php';$i=(require __DIR__.'/../fixtures/printify-connector/batch2/intent.php')();$c=new SyntheticInspectionCore();$h=new VersionedMutationHost($c);return [$i,$c,$h];}
 public function testReceiptImporterAndOperatorViewsExist():void{self::assertTrue(class_exists(ReceiptImporter::class));self::assertTrue(class_exists(OperatorReadModel::class));}
 private function ticket($i,array $r):string{return json_encode(['schema'=>'DF_TRUSTED_RECEIPT_IMPORT_1','operation_id'=>$i->operationId,'scope_fingerprint'=>$i->scope->fingerprint(),'payload_fingerprint'=>$i->payloadFingerprint,'receipt_hash'=>$r['receipt_hash']]);}
 public function testImportResolvesOnlyTrustedCoreReceiptAndIsIdempotent():void{[$i,$c,$h]=$this->setupCore();$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->core->receipt($i);$c->core->receipts[$r['receipt_hash']]=$r;$import=new ReceiptImporter($h);self::assertSame('METADATA_RECONCILED',$import->import($i,$this->ticket($i,$r))['state']);self::assertSame('METADATA_RECONCILED',$import->import($i,$this->ticket($i,$r))['state']);self::assertSame(1,$c->core->receiptCount);}
 /** @dataProvider invalidTicket */
 public function testUnsafeImportDeniedBeforeCoreRead(string $field,mixed $value):void{[$i,$c,$h]=$this->setupCore();$t=json_decode($this->ticket($i,$c->core->receipt($i)),true);$t[$field]=$value;$calls=$c->core->calls;self::assertInstanceOf(WP_Error::class,(new ReceiptImporter($h))->import($i,json_encode($t)));self::assertSame($calls,$c->core->calls);}
 public static function invalidTicket():array{return [['operation_id',str_repeat('0',64)],['scope_fingerprint',str_repeat('0',64)],['payload_fingerprint',str_repeat('0',64)],['receipt_hash','not-hash'],['body',['id'=>'forged']],['schema','unknown'],['credential','private-marker']];}
 public function testAbsentTamperedAndOutOfOrderCoreReceiptsRemainDenied():void{[$i,$c,$h]=$this->setupCore();$f=new MutationFence($h);$f->register($i);$f->reserve($i);$r=$c->core->receipt($i);$import=new ReceiptImporter($h);self::assertInstanceOf(WP_Error::class,$import->import($i,$this->ticket($i,$r)));$r['body']['id']='tampered';$c->core->receipts[$r['receipt_hash']]=$r;self::assertInstanceOf(WP_Error::class,$import->import($i,$this->ticket($i,$r)));$r['sequence']=2;$r['receipt_hash']=ProviderReceipt::hash($r);$c->core->receipts=[$r['receipt_hash']=>$r];self::assertInstanceOf(WP_Error::class,$import->import($i,$this->ticket($i,$r)));self::assertSame(0,$c->core->receiptCount);}
 /** @dataProvider states */
 public function testReadOnlyOperatorStatesAndRedactedEvidence(string $state,string $display):void{[$i,$c,$h]=$this->setupCore();$c->state=$state;$model=new OperatorReadModel($h);$s=$model->snapshot([$i]);self::assertSame($display,$s['items'][0]['state']);self::assertTrue($s['read_only']);self::assertFalse($s['external_execution_authorized']);$json=$model->export([$i]);self::assertIsString($json);foreach(['credential_reference','approval_reference','body','contents','private-marker']as $secret)self::assertStringNotContainsString($secret,$json);$e=json_decode($json,true);$hash=$e['export_hash'];unset($e['export_hash']);self::assertSame($hash,DigiForgePrintifyConnector\Preparation\MutationIntent::hash($e));self::assertStringContainsString($display,OperatorPanel::render($model,[$i]));self::assertSame(0,$c->core->calls);}
 public static function states():array{return [['PREPARED','PREPARED'],['FENCED','RESERVED'],['UNKNOWN','UNKNOWN'],['METADATA_RECONCILED','RECONCILED'],['REJECTED','REJECTED'],['CONFLICTING','CONFLICTING']];}
 /** @dataProvider diagnostics */
 public function testRecoveryDiagnosticsAreNonAuthorizing(string $fault,string $reason):void{[$i,$c,$h]=$this->setupCore();$c->fault=$fault;$s=(new OperatorReadModel($h))->snapshot([$i]);self::assertContains($reason,$s['items'][0]['reasons']);self::assertFalse($s['items'][0]['retry_permitted']);}
 public static function diagnostics():array{return [['stale','SNAPSHOT_STALE'],['missing','JOURNAL_MISSING'],['revoked_approval','APPROVAL_REVOKED'],['unknown','UNRESOLVED_UNKNOWN']];}
 /** @dataProvider invalidInspection */
 public function testInspectionFailsClosed(string $fault):void{[$i,$c,$h]=$this->setupCore();$c->fault=$fault;self::assertInstanceOf(WP_Error::class,(new OperatorReadModel($h))->snapshot([$i]));}
 public static function invalidInspection():array{return array_map(static fn($x)=>[$x],['wrong_shop','tampered_hash','read_revoked','extra_private','unknown_state','wrong_version','invalid_timestamp']);}
 public function testNoCachedInspectionAuthorityAndBoundedExports():void{[$i,$c,$h]=$this->setupCore();$m=new OperatorReadModel($h);self::assertIsArray($m->snapshot([$i]));$c->fault='read_revoked';self::assertInstanceOf(WP_Error::class,$m->export([$i]));self::assertInstanceOf(WP_Error::class,$m->snapshot(array_fill(0,26,$i)));self::assertInstanceOf(WP_Error::class,$m->snapshot([$i,$i]));self::assertInstanceOf(WP_Error::class,(new OperatorReadModel(new VersionedMutationHost()))->snapshot([$i]));}
 public function testAuditExportUsesBoundedSanitizedCoreEvents():void{[$i,$c,$h]=$this->setupCore();$export=json_decode((new OperatorReadModel($h))->export([$i]),true);self::assertArrayHasKey('audit_events',$export['items'][0]);self::assertCount(1,$export['items'][0]['audit_events']);$c->fault='audit_private';self::assertInstanceOf(WP_Error::class,(new OperatorReadModel($h))->export([$i]));}
 public function testMalformedAndOversizedImportNeverReachCore():void{[$i,$c,$h]=$this->setupCore();foreach(['{','null',str_repeat('x',2049)]as $json)self::assertInstanceOf(WP_Error::class,(new ReceiptImporter($h))->import($i,$json));self::assertSame(0,$c->core->calls);}

}
